window.ScripturaLexicons.BDAG_PART_0190 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-01\" data-source=\"BDAG\" data-search=\"κατακυριεύω verbo dominar; subjugar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατακυριεύω</td><td>verbo</td><td>dominar; subjugar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-02\" data-source=\"BDAG\" data-search=\"καταλαλέω verbo difamar; caluniar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλαλέω</td><td>verbo</td><td>difamar; caluniar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-03\" data-source=\"BDAG\" data-search=\"καταλαλιά, ᾶς, ἡ substantivo feminino maledicência; calúnia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλαλιά, ᾶς, ἡ</td><td>substantivo feminino</td><td>maledicência; calúnia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-04\" data-source=\"BDAG\" data-search=\"κατάλαλος, ον adjetivo maledicente; caluniador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάλαλος, ον</td><td>adjetivo</td><td>maledicente; caluniador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-05\" data-source=\"BDAG\" data-search=\"καταλαμβάνω verbo apreender; alcançar; compreender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλαμβάνω</td><td>verbo</td><td>apreender; alcançar; compreender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-06\" data-source=\"BDAG\" data-search=\"καταλάμπω verbo iluminar; resplandecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλάμπω</td><td>verbo</td><td>iluminar; resplandecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-07\" data-source=\"BDAG\" data-search=\"καταλέγω verbo enumerar; selecionar; inscrever BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλέγω</td><td>verbo</td><td>enumerar; selecionar; inscrever</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-08\" data-source=\"BDAG\" data-search=\"κατάλειμμα, ατος, τό substantivo neutro remanescente; resto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάλειμμα, ατος, τό</td><td>substantivo neutro</td><td>remanescente; resto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-09\" data-source=\"BDAG\" data-search=\"καταλείπω verbo deixar; abandonar; legar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλείπω</td><td>verbo</td><td>deixar; abandonar; legar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-10\" data-source=\"BDAG\" data-search=\"καταλιθάζω verbo apedrejar até a morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλιθάζω</td><td>verbo</td><td>apedrejar até a morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-11\" data-source=\"BDAG\" data-search=\"καταλλαγή, ῆς, ἡ substantivo feminino reconciliação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλλαγή, ῆς, ἡ</td><td>substantivo feminino</td><td>reconciliação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-12\" data-source=\"BDAG\" data-search=\"καταλλάσσω verbo reconciliar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλλάσσω</td><td>verbo</td><td>reconciliar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-13\" data-source=\"BDAG\" data-search=\"κατάλοιπος, ον adjetivo remanescente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάλοιπος, ον</td><td>adjetivo</td><td>remanescente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-14\" data-source=\"BDAG\" data-search=\"κατάλυμα, ατος, τό substantivo neutro alojamento; quarto de hóspedes BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάλυμα, ατος, τό</td><td>substantivo neutro</td><td>alojamento; quarto de hóspedes</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-15\" data-source=\"BDAG\" data-search=\"κατάλυσις, εως, ἡ substantivo feminino dissolução; abolição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κατάλυσις, εως, ἡ</td><td>substantivo feminino</td><td>dissolução; abolição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-16\" data-source=\"BDAG\" data-search=\"καταλύω verbo demolir; abolir; hospedar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταλύω</td><td>verbo</td><td>demolir; abolir; hospedar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-17\" data-source=\"BDAG\" data-search=\"καταμανθάνω verbo observar; aprender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταμανθάνω</td><td>verbo</td><td>observar; aprender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-18\" data-source=\"BDAG\" data-search=\"καταμαρτυρέω verbo testemunhar contra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταμαρτυρέω</td><td>verbo</td><td>testemunhar contra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-19\" data-source=\"BDAG\" data-search=\"καταμένω verbo permanecer; habitar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταμένω</td><td>verbo</td><td>permanecer; habitar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0190-20\" data-source=\"BDAG\" data-search=\"καταμόνας advérbio / remissão veja μόνος 3 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καταμόνας</td><td>advérbio / remissão</td><td>veja μόνος 3</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0190-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατακυριεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(<span class=\"greek\">κυριεύω</span>, «ser senhor ou dominador de») futuro <span class=\"greek\">κατακυριεύσω</span>; 1º aoristo <span class=\"greek\">κατεκυρίευσα</span>, imperativo <span class=\"greek\">κατακυρίευσον</span>; 1º aoristo passivo <span class=\"greek\">κατεκυριεύθην</span>.</p><p class=\"entry-text\"> ① submeter, tornar-se senhor, adquirir domínio sobre, subjugar (Diod S 14, 64, 1; Num 21:24; 32:22; Ps 9:26 al.) <span class=\"greek\">τινός</span> (LXX; Test12Patr) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:16</a>. Em sentido figurado, tornar-se senhor, adquirir poder <span class=\"greek\">τινός</span> sobre alguém (TestJud 15:5) ou alguma coisa: <span class=\"greek\">τοῦ διαβόλου</span> Hm 7:2; 12, 4, 7; 12, 6, 4. <span class=\"greek\">τῶν ἔργων τοῦ διαβόλου</span> 12, 6, 2. <span class=\"greek\">τῶν πονηρῶν ἔργων</span> 5, 1, 1. <span class=\"greek\">τῆς διψυχίας</span> dominar a dúvida 9:10. <span class=\"greek\">τῆς ἐπιθυμίας τῆς πονηρᾶς κατακυριεῦσαι</span> dominar o desejo vil 12, 2, 5. <span class=\"greek\">ἃ βλέπεις</span>, <span class=\"greek\">ἐκείνων κατακυρίευε</span> aquilo que vês, procura dominá-lo Hs 9, 2, 7.—Na voz passiva, <span class=\"greek\">ὑπό τινος</span>, deixar-se vencer por alguma coisa Hm 12, 2, 3.</p><p class=\"entry-text\"> ② ter domínio, ser senhor, exercer autoridade sobre, governar <span class=\"greek\">τινός</span> sobre alguém ou alguma coisa (Ps 118:133; Gen 1:28; Sir 17:4; TestNapht 8:6; ApcMos 14; Ar.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:42</a>. <span class=\"greek\">τῆς γῆς</span> B 6:13, 17. <span class=\"greek\">τῶν ὑπὸ τὸν οὐρανὸν πάντων</span> ser senhor de tudo quanto existe debaixo do céu Hm 12, 4, 2; cf. 3. <span class=\"greek\">τῶν κλήρων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:3</a>.—DELG sob o verbete <span class=\"greek\">κύριος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλαλέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro, 3ª pessoa do plural, <span class=\"greek\">καταλαλήσουσιν</span> Mi 3:7; 1º aoristo <span class=\"greek\">κατελάλησα</span> LXX (veja os dois verbetes seguintes e <span class=\"greek\">λαλέω</span>; desde Aristófanes; Polyb.; Stoic. III 237, 6 al.; SIG 593, 6 [século II a.C.]; PHib 151 [cerca de 250 a.C.]; LXX, En; TestAbr B 12 p. 116, 20 [Stone p. 80]; Test12Patr; Philo [apenas em relação ao AT: Leg. All. 2, 66f=Num 12:8 e Leg. All. 2, 78=Num 21:7]) falar mal de, falar depreciativamente de, difamar, caluniar <span class=\"greek\">τινός</span>, alguém (Ps 77:19 <span class=\"greek\">τοῦ θεοῦ</span>; 100:5 <span class=\"greek\">τοῦ πλησίον αὐτοῦ</span>; TestIss 3:4, Gad 5:4; cf. Diod S 11, 44, 6; <span class=\"greek\">τῆς τοῦ θεοῦ δόξης</span> Theoph. Ant. 3, 30 [p. 268, 28]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:11a</a>b; 2 Cl 4:3; Hm 2:2a. <span class=\"greek\">ἵνα ἐν ᾧ καταλαλοῦσιν ὑμῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:12</a> (cf. SIG, local citado <span class=\"greek\">ἵνα μηδ</span>’ <span class=\"greek\">ἐν τούτοις ἔχωσιν ἡμᾶς καταλαλεῖν οἱ</span> … ). Também <span class=\"greek\">κατά τινος</span> (assim predominantemente na LXX e em En) 1 Cl 35:8 (Ps 49:20). Na voz passiva, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:16</a>.—Em sentido figurado, (Pseudo-Luciano, As. 12 <span class=\"greek\">τοῦ λύχνου</span>) <span class=\"greek\">νόμου</span> falar contra a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 4:11c</a>.—Em emprego absoluto, <span class=\"greek\">ὁ καταλαλῶν</span> aquele que fala mal Hm 2:2 (três vezes).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλαλιά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja os verbetes precedente e seguinte; Leontius 18 p. 36, 9; Wsd 1:11; TestGad 3:3; GrBar; AscIs 3, 26; AcPh 142 [Aa II/2, 81, 8].—Os antigos preferiam <span class=\"greek\">κατηγορία</span>. Assim, Tomás Magistro: <span class=\"greek\">καταλαλιὰ οὐδεὶς εἶπε τῶν ἀρχαίων ἀλλ</span>’ <span class=\"greek\">ἀντὶ τούτου κατηγορία</span>) o ato de falar mal de outra pessoa: maledicência, calúnia, difamação, detratação em listas de vícios (veja o verbete <span class=\"greek\">πλεονεξία</span>) no singular e no plural (para indicar ocorrências individuais) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:20</a>; 1 Cl 35:5; B 20:2; Pol 2:2; 4:3; Hm 8:3; Hs 9, 15, 3. <span class=\"greek\">ἀποτίθεσθαι πάσας καταλαλιάς</span> rejeitar todas as calúnias <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:1</a>. <span class=\"greek\">φεύγειν καταλαλιάς</span> evitar a maledicência 1 Cl 30:1; cf. versículo 3; <span class=\"greek\">πιστεύειν τῇ κ</span>. acreditar na calúnia Hm 2:2; <span class=\"greek\">πονηρὰ ἡ κ</span>. 2:3; <span class=\"greek\">κ</span>. prejudica a fé Hs 9, 23, 2; cf. 3.—DELG sob o verbete <span class=\"greek\">λαλέω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάλαλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja os dois verbetes anteriores) relativo a falar mal dos outros: caluniador, maledicente com <span class=\"greek\">δίψυχοι</span> Hs 8, 7, 2. Com <span class=\"greek\">δόλιοι</span> 9, 26, 7. Substantivado, <span class=\"greek\">ὁ κ</span>. (POxy 1828 r, 3) caluniador (numa lista de vícios) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:30</a> (<span class=\"greek\">κακολάλους</span> D); Hs 6, 5, 5.—DELG sob o verbete <span class=\"greek\">λαλέω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλαμβάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">λαμβάνω</span>; desde Homero) 2º aoristo <span class=\"greek\">κατέλαβον</span>; perfeito <span class=\"greek\">κατείληφα</span>. Na voz média: futuro <span class=\"greek\">καταλήψομαι</span> LXX; 2º aoristo <span class=\"greek\">κατελαβόμην</span>. Na voz passiva: futuro, 3ª pessoa do plural, <span class=\"greek\">καταλη</span>(<span class=\"greek\">μ</span>)<span class=\"greek\">θήσονται</span> (PsSol 15:9); 1º aoristo <span class=\"greek\">κατελήμφθην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12</a> (B-D-F §101 p. 53 sob o verbete <span class=\"greek\">λαμβ</span>.; Mlt-H. 246f sob o verbete <span class=\"greek\">λαμβ</span>.; sobre a forma <span class=\"greek\">κατειλήφθη</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:4</a> nas edições mais antigas do NT, veja W-S. §12, 1); perfeito, 3ª pessoa do singular, <span class=\"greek\">κατείληπται</span>; particípio <span class=\"greek\">κατειλημμένος</span>. Em sentido geral, «agarrar, apoderar-se de» (a respeito da apreensão pela força Plut., Cleom. 806 [4, 2]; POxy 1101, 26; PsSol 8:19)</p><p class=\"entry-text\"> ① tornar alguma coisa sua, conquistar, alcançar; nas vozes ativa e passiva (Diog. L. 5, 12 <span class=\"greek\">καταλαμβάνω</span> significa «entrar na posse de uma herança»); em emprego absoluto (embora <span class=\"greek\">τὸ βραβεῖον</span> deva ser suprido pelo contexto) referente à obtenção de um prêmio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:24</a>. Como resultado de <span class=\"greek\">διώκειν</span> (cf. Diod S 17, 73, 3 <span class=\"greek\">ἐπιδιώκων</span> … <span class=\"greek\">τὸν Δαρεῖον</span> … <span class=\"greek\">καταλαβών</span>; Sir 11:10 <span class=\"greek\">ἐὰν διώκῃς</span>, <span class=\"greek\">οὐ μὴ καταλάβῃς</span>; 27:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:12a</a>, 13: <span class=\"greek\">Χριστόν</span>, correspondendo a <span class=\"greek\">κατελήμφθην ὑπὸ Χριστοῦ Ἰ</span>. versículo 12b. <span class=\"greek\">δικαιοσύνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:30</a>. <span class=\"greek\">ἐπίγνωσιν πατρός</span> Dg 10:1 conjectura (vGebhardt, em lugar de <span class=\"greek\">καὶ λάβῃς</span>). O passivo ocorre na acepção «tornar próprio» no final de Marcos do manuscrito Freer 3 (KHaacker, ZNW 63, ’72, 125–29).—Esta também pode ser a acepção de <span class=\"greek\">κ</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:5</a> <span class=\"greek\">ἡ σκοτία αὐτὸ</span> (=<span class=\"greek\">τὸ φῶς</span>) <span class=\"greek\">οὐ κατέλαβεν</span> (-<span class=\"greek\">λαμβάνει</span> Tat. 13, 1; cp. Arrian., An. Alex. 1, 5, 10 <span class=\"greek\">εἰ νὺξ αὐτοὺς καταλήψεται</span> ‘se a noite os alcançasse’; precedido aqui, em 1, 5, 9, por k. na acepção «ocupar» posições acima de uma planície; veja Wetstein sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:5</a> e o item 2b abaixo) as trevas não o apreenderam (Hdb., acerca dessa passagem; assim também Bultmann e, de modo semelhante, JDyer, JBL 79, ’60, 70f: apreciar), caso em que «apreender» passa facilmente à acepção «compreender» (a voz ativa [para a voz média na mesma acepção, veja 4a adiante] tem esta última acepção em Pla., Phdr. 250d; Polyb. 8, 4, 6; Dionys. Hal. 5, 46, 3; PTebt 15, 5; 38, 18; EpArist 1; Aristobul. [Eus., PE 8, 10, 10 e 17=Denis 219, 18 e 221, 5/Holladay p. 140, 2f e 148, 3]; Philo, Mut. Nom. 4; Jos., Vi. 56). A maioria dos comentadores gregos, desde Orígenes, entende <span class=\"greek\">κ</span>. aqui como «vencer, subjugar» (Hdt. 1, 46 <span class=\"greek\">κ</span>. <span class=\"greek\">τινῶν αὐξανομένην τὴν δύναμιν</span>; 1, 87 <span class=\"greek\">τὸ πῦρ</span>; WNagel, ZNW 50, ’59, 132–37). Assim, Goodspeed: «extinguir» (Probs. 93f). Entretanto, talvez João pretendesse incluir aqui ambas as acepções (assim FGingrich, ClW 37, ’43, 77), e uma tradução como «dominar» poderia sugerir essa dupla leitura (assim MSmith, JBL 64, ’45, 510f).</p><p class=\"entry-text\"> ② obter controle de alguém por perseguição: alcançar, capturar, agarrar</p><p class=\"entry-text\"> ⓐ referente às autoridades: alcançar, apanhar (Hdt. 1:63 <span class=\"greek\">τοὺς φεύγοντας</span>; Polyb. 1:47; Gen. 31:23; Judg 18:22; PsSol 15:8) <span class=\"greek\">διωκόμενοι κατελήμφθησαν</span> foram perseguidos e alcançados AcPl Ha 11, 18.</p><p class=\"entry-text\"> ⓑ principalmente a respeito de diversas formas de mal: apoderar-se com intenção hostil, alcançar, sobrevir (Hom.+; frequentemente na LXX; TestSol 2:4 D; Wetstein e Zahn [comentários] sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:5</a> para outros exemplos; veja também SIG 434/5, 14) <span class=\"greek\">μὴ ἡμᾶς καταλάβῃ κακά</span> para que o mal não nos alcance (cf. Gen 19:19; Num 32:23) 2 Cl 10:1; cf. B 4:1. Referente a uma divindade hostil <span class=\"greek\">ὅπου ἐὰν αὐτὸν καταλάβῃ</span> onde quer que ela o agarre (o enfermo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:18</a>.</p><p class=\"entry-text\"> ⓒ empregado especialmente a respeito da noite, do entardecer ou das trevas que surpreendem alguém (Dionys. Hal. 2, 51, 3 <span class=\"greek\">ἑσπέρα γὰρ αὐτοὺς κατέλαβεν</span>; Lucian, Tox. 31; 52; Philo, De Jos. 145; Jos., Ant. 5, 61 <span class=\"greek\">καταλαβοῦσα νύξ</span>, Vi. 329 [GrBar 9:1]. Mas nesses exemplos não se supõe necessariamente que a noite seja algo hostil aos seres humanos em geral. <span class=\"greek\">κ</span>. também pode significar simplesmente «chegar», «sobrevir», como nos numerosos exemplos citados por Wetstein [acima]; veja também Dionys. Hal. 10, 56, 1 <span class=\"greek\">ἐπεὶ κατέλαβεν ὁ τ</span>. <span class=\"greek\">ἀρχαιρεσιῶν καιρός</span>; Strabo 3, 1, 5; Jos., Ant. 4, 78) GJs 14:1 <span class=\"greek\">κατέλαβεν</span> (-<span class=\"greek\">ἐβαλεν</span> pap) <span class=\"greek\">αὐτὸν νύξ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:17</a> v.l. <span class=\"greek\">σκοτία</span>. Em linguagem figurada, com sugestão da acepção 2b: 12:35.</p><p class=\"entry-text\"> ③ surpreender alguém, apanhar de surpresa</p><p class=\"entry-text\"> ⓐ referente às autoridades morais: surpreender, descobrir (PLille 3, 58 [século III a.C.]; Just., D. 47, 5 [dito do Senhor não canônico]; PRyl 138, 15. Especialmente quanto à descoberta de adultério Epict. 2, 4, 1; BGU 1024 III, 11; Sus 58) <span class=\"greek\">τινὰ ἐπί τινι</span>, alguém em alguma coisa <span class=\"greek\">ἐπὶ μοιχείᾳ</span> em adultério (Diod S 10, 20, 2 <span class=\"greek\">ἐπὶ μοιχείᾳ κατειλημμένη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:3</a> uma mulher surpreendida em flagrante adultério. Na voz passiva (Just., A I, 47, 6), com particípio que indica o ato punível <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοφώρῳ μοιχουομένη</span> em flagrante adultério versículo 4.</p><p class=\"entry-text\"> ⓑ referente a um ladrão: na imagem da chegada do «dia», inesperada para os «filhos das trevas» e repleta de perigos para eles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:4</a>.</p><p class=\"entry-text\"> ④ processar informações, entender, compreender</p><p class=\"entry-text\"> ⓐ tomar conhecimento de algo por investigação; na voz média, apreender, descobrir, entender (Dionys. Hal. 2, 66, 6; Sext. Emp., Math. 7, 288; Vett. Val. 225, 8; TestJob 37:6 <span class=\"greek\">τὰ βάθη τοῦ κυρίου</span> al.; Philo, Mos. 1, 278; Jos., Ant. 8, 167; Tat. 4:2 [sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:20</a>]; Ath. 5, 2; 24, 2) com acusativo e infinitivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:25</a>. Seguido de <span class=\"greek\">ὅτι</span> 4:13; 10:34. Seguido de discurso indireto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:18</a>.</p><p class=\"entry-text\"> ⓑ sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:5</a>, veja os itens 1 e 2 acima.—B. 701; 1207. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλάμπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">λάμπω</span>; Eurípides, Platão e outros; PGM 7, 704; Philo; TestGad 7:3 v.l.) iluminar; na voz passiva, ser iluminado, resplandecer (Eur., Tro. 1069, Ion 87; X., Mem. 4, 7, 7) <span class=\"greek\">τινί</span>, por ou com alguma coisa (Cebes 17, 1 <span class=\"greek\">φωτὶ καταλαμπόμενος</span>; Wsd 17:19; Philo, Somn. 1, 218) <span class=\"greek\">ἀκτῖσιν ἡλίου</span> ApcPt 5:15 (Dio Chrys. 19 [36], 45 <span class=\"greek\">τὸ καταλαμπόμενον Ἡλίῳ</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλέγω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Homero e outros; várias acepções, todas caracterizadas por um componente quantitativo que vai do relato de pormenores, como em uma história, «narrar», até o cálculo numérico, «enumerar»; Dt 19:16 «imputar algo a alguém»=«acusar» [cf. a expressão coloquial «contabilizar» as faltas de outra pessoa]; TestSol 8:2 D «relatar integralmente» [como em Just., A I, 46, 3; Ath. 14:2]; Philo, Aet. M. 114; Jos., Ant. 19, 301, C. Ap. 1, 131 al.; Just. [frequentemente «acusar»]; Ath.) selecionar alguém para integrar um grupo (referente a soldados, Aristófanes e outros; Just., A I, 39, 5. Referente à admissão no círculo dos «Doze Deuses» Diod S 4, 39, 4; no Senado, Plut., Pomp. 625 [13, 11]. Cf. Michel 165, 2; BGU 1073, 10) particípio aoristo <span class=\"greek\">καταλέξας</span> (TestSol D 8:2), infinitivo passivo <span class=\"greek\">καταλεχθῆναι</span> (Just., D. 17, 3). <span class=\"greek\">χήρα καταλεγέσθω μὴ ἔλαττον ἐτῶν ἑξήκοντα γεγονυῖα</span> em sentido geral, «ser selecionada», ou, especificamente, «ser inscrita» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:9</a> (para ingresso numa comunidade religiosa, <span class=\"greek\">κ</span>. também é empregado POxy 416, 4. Quanto à construção, cf. o duplo acusativo Pla., Leg. 742e <span class=\"greek\">κ</span>. <span class=\"greek\">τινὰ πλούσιον</span>.).—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάλειμμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Galen; LXX; En 106:18) remanescente, resto (assim em Galeno XIV p. 456, 13 K.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27</a> v.l. (Is 10:22); veja <span class=\"greek\">ὑπόλειμμα</span>.—DELG. sob o verbete <span class=\"greek\">λείπω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλείπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">λείπω</span>; desde Homero) forma alternativa <span class=\"greek\">καταλιμπάνω</span> (LXX; TestIss 6:1; ApcEsdr 3:12 p. 27, 24 Tdf.) imperfeito <span class=\"greek\">κατέλειπον</span>; futuro <span class=\"greek\">καταλείψω</span>; 1º aoristo <span class=\"greek\">κατέλειψα</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a>; Hs 8, 3, 5 v.l.; CPR I, 102; Jos., Bell. 1, 504, Ant. 10, 277); 2º aoristo <span class=\"greek\">κατέλιπον</span> (quanto às formas do aoristo, veja B-D-F §75; W-S. §13, 10; Rob. 348; Helbing 90f; Thackeray 234; Dssm., NB 18 [BS 190]; Crönert 234, 6; KDieterich, Untersuchungen 1898, 238; Mayser 364); perfeito <span class=\"greek\">καταλέλοιπα</span> LXX. Na voz passiva: futuro <span class=\"greek\">καταλειφθήσομαι</span> LXX; 1º aoristo <span class=\"greek\">κατελείφθην</span>; perfeito, 3ª pessoa do singular, <span class=\"greek\">καταλέλειπται</span> (LXX; JosAs 4:13), infinitivo <span class=\"greek\">καταλελεῖφθαι</span>, particípio <span class=\"greek\">καταλελειμμένος</span> (W-S. §5, 13e) «deixar para trás».</p><p class=\"entry-text\"> ① fazer com que alguém ou algo fique num lugar: deixar (para trás)</p><p class=\"entry-text\"> ⓐ referente a pessoas, <span class=\"greek\">τινά</span>, alguém</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. ao partir de um lugar (Diod S 1, 55, 4; 5, 51, 4; Da 10:13; ParJer 3:12; ApcMos 31; Just., D. 2, 3 al.) <span class=\"greek\">καταλείψει ἄνθρωπος τὸν πατέρα κτλ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:31</a> (todos os três textos remetem a Gen 2:24); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:4</a>; 21:17. <span class=\"greek\">κἀκείνους κατέλιπεν αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:19</a>. <span class=\"greek\">κατέλιπόν σε ἐν Κρήτῃ</span>, <span class=\"greek\">ἵνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:5</a> v.l. (em lugar de <span class=\"greek\">ἀπολείπω</span>). <span class=\"greek\">καταλείπω σε ἐν τῷ οἴκω μου</span> GJs 9:3. <span class=\"greek\">ὁ Φῆλιξ κατέλιπεν τ</span>. <span class=\"greek\">Παῦλον δεδεμένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:27</a> (o particípio como em TestReub 3:14); cf. o passivo «ser deixado para trás» (Hippol., Ref. 7, 25, 2) 25:14.—Em outras ocorrências, a voz passiva tem a acepção «permanecer para trás» (X., An. 5, 6, 12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:9</a>. <span class=\"greek\">ἐν Ἀθήναις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:1</a>.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. ao morrer, deixar (sobreviventes) (Hom. et al.; frequentemente nos papiros e na LXX) <span class=\"greek\">γυναῖκα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:19</a>. <span class=\"greek\">σπέρμα</span> descendentes versículo 21 (veja <span class=\"greek\">ἀφίημι</span> 4). <span class=\"greek\">τέκνα</span> (Dt 28:54; cf. Pr 20:7; Jos., Ant. 12, 235) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:31</a>.</p><p class=\"entry-text\"> ⓑ referente a coisas: deixar (para trás) (veja <span class=\"greek\">β</span> acima) <span class=\"greek\">πρόβατα ἐν τῇ ἐρήμῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:4</a>. <span class=\"greek\">πάντα ἐπὶ τ</span>. <span class=\"greek\">γῆς</span> tudo quanto estava em terra 5:11 D. Referente a um jovem que fugia dos guardas <span class=\"greek\">καταλιπὼν τὴν σινδόνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:52</a> (Aesop, Fab. 419 P.=196 H.//301 H-H.: <span class=\"greek\">κατέλιπε τὸν ἑαυτοῦ χιτῶνα</span>; Gen 39:12; TestJos 8:3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:50</a>, veja PDickerson, JBL 116, ’97, 273–89).</p><p class=\"entry-text\"> ② sair de um lugar, com ideia de definitividade: abandonar, deixar (Dio Chrys. 30 [47], 2 <span class=\"greek\">τ</span>. <span class=\"greek\">πατρίδα</span>; Just., D. 60, 2 <span class=\"greek\">τὰ ὑπὲρ οὐρανὸν πάντα</span>) <span class=\"greek\">τὴν Ναζαρά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:13</a>. <span class=\"greek\">Αἴγυπτον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:27</a>. Em sentido figurado, <span class=\"greek\">καταλείποντες εὐθεῖαν ὁδὸν ἐπλανήθησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:15</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ὁδὸν τοῦ θεοῦ ὅλως</span> ApcPt Bodl.—Deixar alguma coisa como está, em seu devido lugar, referente a uma ilha <span class=\"greek\">καταλιπόντες αὐτὴν εὐώνυμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:3</a>.</p><p class=\"entry-text\"> ③ cessar alguma atividade, pôr de lado, desistir referente a um vício <span class=\"greek\">κακίαν</span> 2 Cl 10:1 (ParJer 8:2 <span class=\"greek\">τὰ ἔργα τῆς Βαβυλῶνος</span>). Seguido de infinitivo que indica finalidade: desistir de <span class=\"greek\">τοῦ φυλάσσειν τὸν πύργον</span> parar de guardar a torre Hs 9, 5, 1 referente a jovens que aparentemente tinham deixado de vigiar determinada torre.</p><p class=\"entry-text\"> ④ fazer algo subsistir ou sobrar: deixar como remanescente (Alex. Aphr., Fat. 28, II 2 p. 199, 8) <span class=\"greek\">τὰ θηρία</span> … <span class=\"greek\">ἵνα μηδὲν καταλίπωσι τῶν τοῦ σώματός μου</span> para que não deixem sequer um pedaço do meu corpo IRo 4:2. Na voz passiva, permanecer (Jos., Bell. 4, 338 <span class=\"greek\">σωτηρίας ἐλπίς</span>; Iren. 1, 16, 1 [Harv. I 158, 12]; Hippol., Ref. 7, 31, 8), especificamente na acepção «ficar incompleto, inacabado, ainda em aberto» (X., Cyr. 2, 3, 11 <span class=\"greek\">μάχη</span>; PLond III, 1171, 43 [8 a.C.]) <span class=\"greek\">καταλειπομένη ἐπαγγελία</span> uma promessa que continua em vigor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:1</a>.—Deixar como remanescente; assegurar que algo permaneça (cf. Sir 24:33) <span class=\"greek\">κατέλιπον ἐμαυτῷ ἑπτακισχιλίους ἄνδρας</span> reservei para mim 7.000 homens <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:4</a> (3 Km 19:18; aqui, como no hebraico, emprega-se a primeira pessoa).</p><p class=\"entry-text\"> ⑤ deixar intencionalmente algo antes de partir, legar como herança (Mel., P. 49, 347–79) Hv 3, 12, 2.</p><p class=\"entry-text\"> ⑥ deixar alguém entregue aos próprios recursos: abandonar</p><p class=\"entry-text\"> ⓐ por deserção ou abandono, deixar para trás, desertar MPol 17:2, Cristo (Sir 28:23 <span class=\"greek\">κύριον</span>; Just., D. 8, 3 <span class=\"greek\">θεόν</span>).</p><p class=\"entry-text\"> ⓑ deixar sem auxílio <span class=\"greek\">τινά</span>, com infinitivo de resultado (não de finalidade; veja B-D-F §392, 1f; Rob. 1090, e cf. Il. 17, 151) <span class=\"greek\">ἡ ἀδελφή μου μόνην με κατέλιπεν διακονεῖν</span> minha irmã deixou-me sem ajuda, de modo que agora tenho de servir sozinha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:40</a> (v.l. <span class=\"greek\">κατέλειπεν</span>; quanto a <span class=\"greek\">κ</span>. <span class=\"greek\">ἐμὲ μόνον</span>, cf. Jos., Vi. 301).</p><p class=\"entry-text\"> ⑦ pôr algo de lado em favor de outra coisa: abandonar</p><p class=\"entry-text\"> ⓐ abandonar <span class=\"greek\">ἀλήθειαν</span> Hs 8, 9, 1.</p><p class=\"entry-text\"> ⓑ renunciar (por exemplo, escólio sobre Apolônio de Rodes 272–74 <span class=\"greek\">τὴν τέχνην</span> abandonar o próprio ofício); perder (Petosiris, Fgm. 12 linhas 22 e 120 <span class=\"greek\">τὸν θρόνον</span>) <span class=\"greek\">πάντα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:28</a>; cf. 1 Cl 10:2; <span class=\"greek\">τὴν παροικίαν τ</span>. <span class=\"greek\">κόσμου τούτου</span> 2 Cl 5:1.</p><p class=\"entry-text\"> ⓒ pôr de lado, negligenciar (Ps.-X., Cyneg. 3, 10 <span class=\"greek\">τὰ αὑτῶν ἔργα</span>; Dt 29:24 <span class=\"greek\">τ</span>. <span class=\"greek\">διαθήκην</span>; Jos., Ant. 8, 190 <span class=\"greek\">τ</span>. <span class=\"greek\">τῶν πατρίων ἐθισμῶν φυλακήν</span>; TestIss 6:1 <span class=\"greek\">τὴν ἁπλότητα</span>) <span class=\"greek\">ἄμπελος ἐν φραγμῷ τινι καταλειφθεῖσα</span> como uma videira deixada à própria sorte sobre uma cerca Hs 9, 26, 4. <span class=\"greek\">τὸν λόγον τ</span>. <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:2</a>.—DELG sob o verbete <span class=\"greek\">λίθος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλιθάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">λιθάζω</span>) futuro <span class=\"greek\">καταλιθάσω</span> (somente em escritores cristãos Mas <span class=\"greek\">καταλιθοβολέω</span> Ex 17:4; Num 14:10 e <span class=\"greek\">καταλιθόω</span> em Pausânias; Jos., Ant. 4, 282 al.) apedrejar até a morte <span class=\"greek\">τινά</span>, alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:6</a>.—DELG sob o verbete <span class=\"greek\">λίθος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλλαγή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o verbete seguinte) restabelecimento de uma relação interrompida ou rompida: reconciliação (assim em Aeschyl., Sept. 767; Demosth. 1, 4) com Deus (2 Macc 5:20; Philo, Exs. 166 <span class=\"greek\">αἱ πρὸς τὸν πατέρα</span> [=Deus] <span class=\"greek\">καταλλαγαί</span> [em Fílon, sempre no plural]), a qual, segundo Paulo, é realizada exclusivamente por Deus (veja <span class=\"greek\">καταλλάσσω</span>, alínea a). <span class=\"greek\">κ</span>. <span class=\"greek\">κόσμου</span> (oposto a <span class=\"greek\">ἀποβολή</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:15</a>; <span class=\"greek\">λόγος τῆς κ</span>. a palavra da reconciliação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:19</a> (cf. a função dos juízes [IPriene 53] e dos emissários [Dio Chrys. 38, 18], veja FDanker, Augsburg Comm: II Cor ’89, 83; Breytenbach 64f; veja também <span class=\"greek\">διαλλασσομαι</span> e <span class=\"greek\">πρεσβεύω</span>) <span class=\"greek\">διακονία τῆς κ</span>. ministério da reconciliação versículo 18. Como os seres humanos não são agentes ativos nesta dispensação procedente de Deus, diz-se que eles <span class=\"greek\">τ</span>. <span class=\"greek\">καταλλαγὴν λαμβάνειν</span> recebem a reconciliação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:11</a>.—EGvanLeeuwen, De <span class=\"greek\">καταλλαγή</span>: ThSt 28, 1910, 159–71; ANygren, D. Versöhnung als Gottestat ’32; CBreytenbach, Versöhnung, ’89; idem NTS 39, ’93, 59–79; AdeOliveira, Die Diakonie der Gerechtigkeit und der Versöhnung in der Apologie des 2 Korintherbriefes, ’90.—EDNT. DELG sob o verbete <span class=\"greek\">ἄλλος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλλάσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o verbete precedente e <span class=\"greek\">διαλλάσσω</span>) 1º aoristo <span class=\"greek\">κατήλλαξα</span>; aoristo médio, 3ª pessoa do plural, <span class=\"greek\">κατηλλάξαντο</span> (TestAbr A 8 p. 85, 30 [Stone p. 18]). Na voz passiva: futuro, 3ª pessoa do singular, <span class=\"greek\">καταλλαγήσεται</span> 2 Macc 7:33; 2º aoristo <span class=\"greek\">κατηλλάγην</span>; particípio <span class=\"greek\">καταλλαγείς</span>; em sentido geral, «trocar» uma coisa por outra (TestJob 25:3 <span class=\"greek\">τρίχα</span> … <span class=\"greek\">ἀντὶ ἄρτων</span>); no corpus aqui considerado, apenas a substituição da hostilidade por uma relação amistosa: reconciliar (assim em Hdt. e outros; 2 Macc). Na voz ativa, <span class=\"greek\">τινά</span> (Hdt. 5, 29; 6, 108; Aristot., Oec. 2, 15) alguém <span class=\"greek\">τινί</span>, com alguém.</p><p class=\"entry-text\"> ⓐ voz ativa, referente à ação de Deus, <span class=\"greek\">ἡμᾶς ἑαυτῷ διὰ Χριστοῦ</span> a nós consigo mesmo por meio de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:18</a>=<span class=\"greek\">ἐν Χριστῷ κόσμον ἑαυτῷ</span> versículo 19.</p><p class=\"entry-text\"> ⓑ voz passiva</p><p class=\"entry-text\"> <span class=\"greek\">α</span>. ser reconciliado, reconciliar-se (BGU 1463, 3 [247 a.C.]; Philo, Leg. All. 3, 134) com dativo de pessoa (cf. X., An. 1, 6, 2; Pla., Rep. 8, 566e; 2 Macc 1:5; 7:33; 8:29; Jos., Ant. 7, 184): referente à relação da humanidade com Deus (Soph., Aj. 744; Jos., Ant. 6, 143 <span class=\"greek\">θεὸν καταλλάττεσθαι τῷ Σαούλῳ</span>) <span class=\"greek\">καταλλαγῆναι τῷ θεῷ</span> ser reconciliado com Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:10a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:20</a> (formulação semelhante, mas sentido diferente Vi. Aesopi G 100 P. Esopo suplica ao rei <span class=\"greek\">καταλλάγηθι Σαμίοις</span>; cf. Vi. Aesopi W 100 P. <span class=\"greek\">δέομαι σου</span>, <span class=\"greek\">δέσποτα</span>, <span class=\"greek\">διαλλάγηθι Σαμίοις</span>, seguido da resposta do rei: <span class=\"greek\">κατήλλαγμαι</span>; quanto à função de emissário ou mediador, veja o verbete precedente). Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:10b</a>.</p><p class=\"entry-text\"> <span class=\"greek\">β</span>. Referente à reconciliação entre seres humanos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:22</a> D. (<span class=\"greek\">γυνὴ</span>) <span class=\"greek\">τῷ ἀνδρὶ καταλλαγήτω</span> que ela se reconcilie com seu marido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:11</a> (cf. POxy 104, 27 [século I d.C.]; a hipótese, [resumo] de Aristófanes, o Gramático, sobre o Dyscolus de Menandro, ln. 9: <span class=\"greek\">κατηλλάγη τῇ γυναικί</span>).—DELG sob o verbete <span class=\"greek\">ἄλλος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάλοιπος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">λοιπός</span>; Platão e outros; inscrições, papiros, LXX) restante, remanescente <span class=\"greek\">οἱ κ</span>. <span class=\"greek\">τῶν ἀνθρώπων</span> o restante da humanidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:17</a> (Am 9:12).—DELG sob o verbete <span class=\"greek\">λείπω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάλυμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(Polyb. 2, 36, 1; 32, 19, 2; Diod S 14, 93, 5; IG V/1, 869; SIG 609, 1; UPZ 120, 5 [século II a.C.] e outros exemplos em papiros; LXX; TestLevi 3:4 v.l.; veja B-D-F §109, 2; Rob. 151) local de hospedagem. A acepção «hospedaria» é possível em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:7</a>, mas em 10:34 Lucas emprega <span class=\"greek\">πανδοχεῖον</span>, termo mais específico para «hospedaria». <span class=\"greek\">κ</span>. é, portanto, mais bem entendido aqui como «alojamento» (PSI 341, 8 [256 a.C.]; EpArist 181) ou «quarto de hóspedes», como em 22:11 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:14</a>, cujos contextos também admitem a acepção «sala de refeições» (cf. 1 Km 1:18; 9:22; Sir 14:25). Em apoio adicional a essa tradução está o contraste entre dois espaços: uma <span class=\"greek\">φάτνη</span> e um <span class=\"greek\">κατάλυμα</span>. Este último podia constituir um espaço em vários tipos de construções. Cf. também o emprego do cognato <span class=\"greek\">καταλύω</span> (veja <span class=\"greek\">κ</span>., acepção 4) em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:7</a>, com referência à hospitalidade.—PBenoit, BRigaux Festschr., ’70, 173–86 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:7</a>); EPax, Bibel und Leben 6, ’65, 285–98. DELG sob o verbete <span class=\"greek\">λύω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κατάλυσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja <span class=\"greek\">καταλύω</span> 1–3; desde Tucídides; inscrições; PMagd 8, 10 [218 a.C.] <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ βίου</span>; LXX; En 5:6; Philo; Jos., Bell. 2, 594, Ant. 18, 55; 19, 301 al.; Just.) dissolução, abolição; também queda (referente a um tirano: Diod S 14, 64, 4; 14, 67, 1) <span class=\"greek\">θανάτου</span> IEph 19:3.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταλύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(veja o verbete anterior para as acepções 1–3 e <span class=\"greek\">κατάλυμα</span> para a acepção 4) futuro <span class=\"greek\">καταλύσω</span>; 1º aoristo <span class=\"greek\">κατέλυσα</span>; infinitivo perfeito <span class=\"greek\">καταλελυκέναι</span> (Just., D. 41, 1). Na voz passiva: 1º futuro <span class=\"greek\">καταλυθήσομαι</span>; 1º aoristo <span class=\"greek\">κατελύθην</span> (Hom.+).</p><p class=\"entry-text\"> ① desprender algo num processo de demolição, derrubar, deslocar referente a uma pedra retirada de uma construção <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:6</a>.</p><p class=\"entry-text\"> ② causar a ruína de algo: destruir, demolir, desmantelar</p><p class=\"entry-text\"> ⓐ literalmente, referente a edifícios (Hom. et al.; 2 Esdr 5:12; Jos., Ant. 9, 161 <span class=\"greek\">τ</span>. <span class=\"greek\">ναοῦ</span> [<span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>] <span class=\"greek\">καταλυθέντος</span>; SibOr 3, 459) <span class=\"greek\">τ</span>. <span class=\"greek\">ναὸν τοῦ θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:61</a>; cf. 27:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:58</a>; 15:29. <span class=\"greek\">τὸν τόπον τοῦτον</span> este lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:14</a>.</p><p class=\"entry-text\"> ⓑ em sentido figurado (oposto a <span class=\"greek\">οἰκοδομεῖν</span>), derrubar, demolir <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:18</a>. Referente ao corpo como tenda terrena <span class=\"greek\">ἐὰν ἡ ἐπίγειος ἡμῶν οἰκία τοῦ σκήνους καταλυθῇ</span> se a tenda terrena em que habitamos for destruída ou desmontada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1</a>. <span class=\"greek\">τὸ ἔργον τοῦ θεοῦ</span> destruir a obra (isto é, a congregação cristã, provavelmente concebida como edifício de Deus devido ao versículo 19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:20</a>. Em contrapartida, a figura do edifício não está presente, e encontra-se a acepção geral «destruir, aniquilar» (Strabo 13, 2, 3 p. 617; Ael. Aristid. 29 p. 570 D.: <span class=\"greek\">ἐλπίδας</span>; TestBenj 3:8) em <span class=\"greek\">τὰ ἔργα τῆς θηλείας</span> (veja <span class=\"greek\">ἔργον</span> 3, final) GEg 252, 55.</p><p class=\"entry-text\"> ③ pôr fim ao efeito ou à validade de alguma coisa: extinguir</p><p class=\"entry-text\"> ⓐ fazer com que algo deixe de vigorar: abolir, anular, invalidar (Hdt.+) <span class=\"greek\">κ</span>. <span class=\"greek\">τὸν νόμον</span> abolir, anular ou revogar a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17a</a> (cf. X., Mem. 4, 4, 14; Isocr. 4, 55; Diod S 34+35 Fgm. 3 e 40, 2 [referente à intenção dos selêucidas contra os judeus: <span class=\"greek\">καταλύειν τοὺς πατρίους νόμους</span>]; Philostrat., Vi. Apoll. 4, 40; 2 Macc 2:22; Philo, Somn. 2, 123; Jos., Ant. 16, 35; 20, 81; Ath., R. 19 p. 72, 28). <span class=\"greek\">τ</span>. <span class=\"greek\">νόμον κ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">προφήτας</span> (semelhante a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17a</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:2</a> v.l. <span class=\"greek\">τὰς θυσίας</span> abolir os sacrifícios GEb 54, 20. Em emprego absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:17b</a> (oposto a <span class=\"greek\">πληροῦν</span>); D 11:2.</p><p class=\"entry-text\"> ⓑ fazer cessar, arruinar, (Appian, Prooem. C. 10 §42 <span class=\"greek\">ἀρχάς</span>=impérios; Arrian, Anab. 4, 10, 3 <span class=\"greek\">τυραννίδα</span>; 4 Macc 4:24 <span class=\"greek\">τὰς ἀπειλάς</span>; Jos., Ant. 12, 1 <span class=\"greek\">τὴν Περσῶν ἡγεμονίαν</span>) <span class=\"greek\">ἡ βουλὴ καταλυθήσεται</span> o plano fracassará <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:38</a>. Também referente a pessoas (TestJob 34:5; Just., D. 100, 6 al.; Diod S 16, 47, 2 <span class=\"greek\">τοὺς μάγους</span>; Appian, Bell. Civ. 1, 48 §210) suprimir, deter versículo 39. Referente a governantes depostos (Diod S 1, 66, 6; 9, 4, 2 [um tirano]; 14, 14, 7 al.; Polyaenus 7, 3 e 10; 8, 29; IAndrosIsis, Kyme 25) <span class=\"greek\">καταλύεται ὁ ἄρχων τοῦ αἰῶνος τούτου</span> o governante deste século é deposto ITr 4:2.</p><p class=\"entry-text\"> ④ cessar o que se faz, parar (literalmente, «desatrelar os animais de carga»), descansar, encontrar hospedagem (Thu. et al.; SIG 978, 8; UPZ 12, 37 [158 a.C.]; 62, 34; BGU 1097, 5; Gen 19:2; 24:23, 25; Sir 14:25, 27; 36:27; JosAs 3:3; Jos., Vi. 248; Just., D. 78, 5 [ref. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:7</a>]; cf. En 5:6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:12</a>. Com <span class=\"greek\">εἰσέρχεσθαι</span> 19:7.—B. 758. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταμανθάνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">2º aoristo <span class=\"greek\">κατέμαθον</span> (veja <span class=\"greek\">μανθάνω</span>; desde Heródoto; inscrições, papiros, LXX; En 3:1; Philo; Jos., Ant. 6, 230f, Vi. 10; Just., D. 120, 2; Tat.) observar atentamente, perceber, aprender <span class=\"greek\">τὶ</span>, alguma coisa <span class=\"greek\">τοὺς καιρούς</span> IPol 3:2. Seguido de <span class=\"greek\">ὅτι</span> (Hippocr., Art. 8 p. 122, 2 Kühlewein) 1 Cl 7:5. Com acusativo seguido de <span class=\"greek\">ὅτι</span> (Aristot., Pol. 3, 14, 1285a, 1; Philo, Leg. All. 3, 183) 2 Cl 13:3. Com acusativo seguido de <span class=\"greek\">πῶς</span>: <span class=\"greek\">τὰ κρίνα τοῦ ἀγροῦ πῶς αὐξάνουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:28</a>. <span class=\"greek\">τοὺς ἑτεροδοξοῦντας</span> … <span class=\"greek\">πῶς ἐναντίοι εἰσίν</span> ISm 6:2.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταμαρτυρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταμαρτυρήσω</span> LXX; aoristo <span class=\"greek\">κατεμαρτύρησα</span> LXX (veja <span class=\"greek\">μαρτυρέω</span>; Lísias, Demóstenes; PPetr III, 17; I, 9; UPZ 162 V, 33 [117 a.C.]; LXX; Philo, Leg. All. 3, 199; Jos., Ant. 8, 358; 359) prestar testemunho contra, depor contra <span class=\"greek\">τί τινος</span>, testemunhar alguma coisa contra alguém (Plut., Ages. 3, 9; Pr 25:18; Sus 43; 49 Theod.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.62\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:62</a>; 27:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:60</a>; 15:4 v.l.—DELG sob o verbete <span class=\"greek\">μάρτυς</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταμένω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">futuro <span class=\"greek\">καταμενῶ</span>; aoristo <span class=\"greek\">κατέμεινα</span> LXX (veja <span class=\"greek\">μένω</span>; Heródoto, Aristófanes e outros; inscrições, papiros, LXX; TestLevi 9:5; EpArist, Philo; Jos., Ant. 6, 249; 7, 180) permanecer, habitar <span class=\"greek\">οὗ ἦσαν καταμένοντες</span> onde estavam alojados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:13</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">πρός τινα</span> permanecer com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:6</a> v.l. (em lugar de <span class=\"greek\">παραμενῶ</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0190-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καταμόνας</h1><div class=\"entry-meta\"><span>advérbio / remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">leitura do texto recebido; veja <span class=\"greek\">μόνος</span> 3.</p></section></article>\n"};
